"use client"

/**
 * Clean-room shared-element popover. A surface shared with the trigger
 * grows into the panel via motion `layoutId`. Blendy is the behavior
 * reference only and is not a dependency. Reduced motion fades the panel
 * in place. Escape, outside pointer, and focus return are handled. The
 * popover is non-modal: Tab may leave it.
 */

import * as React from "react"
import { AnimatePresence, LayoutGroup, motion } from "motion/react"

import { cn } from "@/lib/utils"
import { useOverlayFocus } from "@/lib/overlay-focus"
import { motionPresets } from "@/lib/motion"
import { useMotionPreference } from "@/components/ui/motion-preference"

export type MorphPopoverProps = {
  label: React.ReactNode
  title?: React.ReactNode
  children?: React.ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  className?: string
  triggerClassName?: string
  panelClassName?: string
}

export function MorphPopover({
  label,
  title,
  children,
  open,
  defaultOpen = false,
  onOpenChange,
  className,
  triggerClassName,
  panelClassName,
}: MorphPopoverProps) {
  const reduced = useMotionPreference()
  const uid = React.useId()
  const layoutId = reduced ? undefined : `${uid}-surface`
  const titleId = `${uid}-title`
  const panelId = `${uid}-panel`
  const rootRef = React.useRef<HTMLDivElement>(null)
  const panelRef = React.useRef<HTMLDivElement>(null)
  const [internal, setInternal] = React.useState(defaultOpen)
  const isOpen = open ?? internal

  const setOpen = React.useCallback(
    (next: boolean) => {
      if (open === undefined) setInternal(next)
      onOpenChange?.(next)
    },
    [onOpenChange, open],
  )

  const close = React.useCallback(() => setOpen(false), [setOpen])
  useOverlayFocus(isOpen, panelRef, close, false)

  React.useEffect(() => {
    if (!isOpen) return
    function onPointer(event: PointerEvent) {
      if (!rootRef.current?.contains(event.target as Node)) close()
    }
    document.addEventListener("pointerdown", onPointer)
    return () => document.removeEventListener("pointerdown", onPointer)
  }, [close, isOpen])

  const transition = reduced ? { duration: 0 } : motionPresets.spring.morph

  return (
    <LayoutGroup>
      <div ref={rootRef} className={cn("relative inline-flex", className)}>
        <button
          type="button"
          className={cn(
            "relative inline-flex h-8 items-center justify-center rounded-lg border border-border bg-background px-2.5 text-sm font-medium",
            triggerClassName,
          )}
          aria-expanded={isOpen}
          aria-controls={panelId}
          onClick={() => setOpen(!isOpen)}
        >
          {!isOpen || reduced ? (
            <motion.span
              layoutId={layoutId}
              className="absolute inset-0 rounded-lg border border-border bg-muted"
              style={{ borderRadius: 8 }}
              transition={transition}
              aria-hidden="true"
            />
          ) : null}
          <span className="relative">{label}</span>
        </button>
        <AnimatePresence>
          {isOpen ? (
            <motion.div
              ref={panelRef}
              id={panelId}
              role="dialog"
              aria-modal="false"
              aria-labelledby={title ? titleId : undefined}
              tabIndex={-1}
              layoutId={layoutId}
              className={cn(
                "absolute top-[calc(100%+0.5rem)] left-0 z-30 flex w-64 flex-col gap-2 border border-border bg-popover p-3 text-popover-foreground shadow-lg outline-none",
                panelClassName,
              )}
              style={{ borderRadius: 12 }}
              transition={transition}
              initial={reduced ? { opacity: 0 } : false}
              animate={{ opacity: 1 }}
              exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0 }}
            >
              {title ? (
                <p id={titleId} className="text-sm font-medium">
                  {title}
                </p>
              ) : null}
              {children}
            </motion.div>
          ) : null}
        </AnimatePresence>
      </div>
    </LayoutGroup>
  )
}

"use client"

import * as React from "react"

const FOCUSABLE = [
  "a[href]",
  "button:not([disabled])",
  "textarea:not([disabled])",
  "input:not([disabled])",
  "select:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(",")

export function focusableElements(root: HTMLElement) {
  return [...root.querySelectorAll<HTMLElement>(FOCUSABLE)].filter(
    (element) => !element.hasAttribute("disabled") && element.tabIndex !== -1 && !element.closest("[hidden]"),
  )
}

/** First control that is not a dismiss button, then the dismiss button, then the panel. */
function initialFocusTarget(node: HTMLElement) {
  const items = focusableElements(node)
  const content = items.find((element) => element.dataset.overlayClose === undefined)
  return content ?? items[0] ?? node
}

/**
 * Moves focus into an overlay, restores it on close, and closes on Escape.
 * `trap` cycles Tab inside the panel (modal dialogs).
 */
export function useOverlayFocus(
  open: boolean,
  panelRef: React.RefObject<HTMLElement | null>,
  onClose: () => void,
  trap: boolean,
  returnFocusRef?: React.RefObject<HTMLElement | null>,
) {
  const onCloseRef = React.useRef(onClose)
  React.useEffect(() => {
    onCloseRef.current = onClose
  }, [onClose])

  React.useEffect(() => {
    if (!open) return
    const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null
    const returnNode = returnFocusRef?.current ?? null
    const node = panelRef.current
    if (node) initialFocusTarget(node).focus()

    function onKey(event: KeyboardEvent) {
      if (event.key === "Escape") {
        event.preventDefault()
        onCloseRef.current()
        return
      }
      if (!trap || event.key !== "Tab" || !node) return
      const items = focusableElements(node)
      if (!items.length) {
        event.preventDefault()
        node.focus()
        return
      }
      const first = items[0]
      const last = items[items.length - 1]
      const active = document.activeElement
      if (event.shiftKey && (active === first || active === node)) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && active === last) {
        event.preventDefault()
        first.focus()
      }
    }

    document.addEventListener("keydown", onKey)
    return () => {
      document.removeEventListener("keydown", onKey)
      const target = returnNode?.isConnected ? returnNode : previous
      if (target?.isConnected) target.focus()
    }
  }, [open, panelRef, returnFocusRef, trap])
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    // Exit decelerates, the same curve as CSS ease-out.
    exit: [0, 0, 0.58, 1] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
